/**
 * Cinejoy webOS - Content Details & TV Episode Selector View Controller
 * File: app/js/views/details.js
 * Standard: 10-Foot Television UX, webOS 8.5.0 (Chromium ~108+)
 * Modernized: Google TV Cinema Full-Bleed Overlay & Sleek Cast Chips
 * Invariants: Zero DOM Sinks (.innerHTML / .outerHTML), 11 Invariant DOM IDs Preserved
 */

(function (global) {
  'use strict';

  function getCardFactory() {
    return global.CardFactory || {};
  }

  function clearElement(element) {
    if (!element) return;
    while (element.firstChild) {
      element.removeChild(element.firstChild);
    }
  }

  var DetailsViewController = {
    initialized: false,
    item: null,
    detailsData: null,
    activeSeason: 1,
    container: null,

    init: function () {
      if (this.initialized) return;
      this.initialized = true;

      this.container = document.getElementById('view-details');
      this.bindActions();
    },

    bindActions: function () {
      var self = this;

      // Primary Play Action
      var playBtn = document.getElementById('details-play-btn');
      if (playBtn && !playBtn._hasBoundDetailsPlay) {
        playBtn._hasBoundDetailsPlay = true;
        playBtn.addEventListener('click', function () {
          if (!self.item || !global.CinejoyApp) return;
          var mediaType = self.item.media_type || self.item.type || 'movie';
          var payload = {
            tmdbId: self.item.id || self.item.tmdbId,
            type: mediaType,
            title: self.item.title || self.item.name
          };

          if (mediaType === 'tv') {
            payload.season = self.activeSeason;
            payload.episode = 1;
          }

          global.CinejoyApp.switchView('player', payload);
        });
      }

      // Back Action Button
      var backBtn = document.getElementById('details-back-btn');
      if (backBtn && !backBtn._hasBoundDetailsBack) {
        backBtn._hasBoundDetailsBack = true;
        backBtn.addEventListener('click', function () {
          if (global.CinejoyApp && global.CinejoyApp.handleBackNavigation) {
            global.CinejoyApp.handleBackNavigation();
          } else if (window.history && window.history.back) {
            window.history.back();
          }
        });
      }

      // Trailer Action Button
      var trailerBtn = document.getElementById('details-trailer-btn');
      if (trailerBtn && !trailerBtn._hasBoundDetailsTrailer) {
        trailerBtn._hasBoundDetailsTrailer = true;
        trailerBtn.addEventListener('click', function () {
          if (self.detailsData && self.detailsData.videos && self.detailsData.videos.results) {
            var trailer = self.detailsData.videos.results.find(function (v) {
              return v.site === 'YouTube' && (v.type === 'Trailer' || v.type === 'Teaser');
            });
            if (trailer && global.CinejoyApp && global.CinejoyApp.showToast) {
              global.CinejoyApp.showToast('Trailer: ' + (trailer.name || trailer.key));
            }
          }
        });
      }

      // Delegate Episode Card Clicks
      if (this.container && !this.container._hasBoundDetailsClicks) {
        this.container._hasBoundDetailsClicks = true;
        this.container.addEventListener('click', function (e) {
          var epCard = e.target.closest('.card-episode');
          if (!epCard || !global.CinejoyApp) return;

          var season = parseInt(epCard.getAttribute('data-season') || String(self.activeSeason || 1), 10);
          var episode = parseInt(epCard.getAttribute('data-episode') || '1', 10);
          var epTitle = epCard.getAttribute('data-title') || '';
          var item = self.item || self.detailsData || {};

          global.CinejoyApp.switchView('player', {
            tmdbId: item.id || item.tmdbId,
            type: 'tv',
            season: season,
            episode: episode,
            title: item.title || item.name || '',
            episodeTitle: epTitle
          });
        });
      }
    },

    activate: function (item) {
      this.init();
      if (item) {
        this.item = item;
        var mediaType = item.media_type || item.type || (item.first_air_date ? 'tv' : 'movie');
        var id = item.id || item.tmdbId;
        if (id) {
          this.loadDetails(id, mediaType);
        } else {
          this.bindHero(item, mediaType);
        }
      }
    },

    loadDetails: function (id, mediaType) {
      var self = this;
      var mType = mediaType || 'movie';
      if (!this.initialized) this.init();
      if (!this.item) {
        this.item = { id: id, tmdbId: id, type: mType, media_type: mType };
      }
      if (!global.TmdbClient) return;

      return global.TmdbClient.getDetails(mType, id).then(function (data) {
        if (!data || data.error) return;
        self.detailsData = data;
        if (!self.item || !self.item.title) {
          self.item = Object.assign({ id: id, tmdbId: id, type: mType, media_type: mType }, data);
        }
        self.bindHero(data, mType);

        var castList = data.cast || (data.credits && data.credits.cast) || [];
        self.renderCast(castList);

        if (mType === 'tv') {
          var numSeasons = data.numberOfSeasons || data.number_of_seasons || (data.seasons ? data.seasons.length : 1);
          self.renderSeasonSelector(numSeasons);
          self.loadSeason(id, self.activeSeason || 1);
          self.hideRecommendations();
        } else {
          self.hideSeasonSelector();
          var recs = data.recommendations || (data.recommendations && data.recommendations.results) || [];
          if (!recs.length && data.similar) {
            recs = data.similar;
          }
          self.renderRecommendations(recs);
        }
      }).catch(function (err) {
        console.error('[DetailsViewController] Failed to load details:', err);
      });
    },

    bindHero: function (data, mediaType) {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var backdropPath = data.backdrop_path || data.backdropUrl;
      var backdropImg = document.getElementById('details-backdrop-img') || this.container.querySelector('.details-backdrop-img');
      if (backdropImg) {
        var backdropUrl = data.backdropUrl || (backdropPath && backdropPath.indexOf('http') === 0 ? backdropPath : (global.TmdbClient ? global.TmdbClient.getBackdropUrl(backdropPath, 'original') : 'https://image.tmdb.org/t/p/original/xOMo8BRK7PfcJv9JCnx7s520dQe.jpg'));
        backdropImg.src = backdropUrl;
      }

      var titleEl = document.getElementById('details-title');
      if (titleEl) {
        titleEl.textContent = data.title || data.name || 'Untitled';
      }

      var ratingVal = data.ratingDisplay || (typeof data.vote_average === 'number' ? data.vote_average.toFixed(1) : (data.vote_average ? String(data.vote_average) : (data.rating ? String(data.rating) : 'NR')));
      var ratingEl = document.getElementById('details-meta-rating');
      if (ratingEl) {
        ratingEl.textContent = ratingVal !== 'NR' ? ('★ ' + ratingVal) : 'NR';
      }

      var releaseDate = data.release_date || data.first_air_date || data.releaseDate || '';
      var year = String(data.year || releaseDate).slice(0, 4) || '—';
      var yearEl = document.getElementById('details-meta-year');
      if (yearEl) {
        yearEl.textContent = year;
      }

      var runtimeEl = document.getElementById('details-meta-runtime');
      if (runtimeEl) {
        var runtimeStr = '';
        if (data.runtime) {
          runtimeStr = Math.floor(data.runtime / 60) + 'h ' + (data.runtime % 60) + 'm';
        } else if (data.episode_run_time && data.episode_run_time.length) {
          runtimeStr = data.episode_run_time[0] + 'm';
        } else if (data.number_of_seasons) {
          runtimeStr = data.number_of_seasons + ' Season' + (data.number_of_seasons > 1 ? 's' : '');
        } else {
          runtimeStr = '—';
        }
        runtimeEl.textContent = runtimeStr;
      }

      var qualityEl = document.getElementById('details-meta-quality');
      if (qualityEl) {
        qualityEl.textContent = data.quality || '4K UHD';
      }

      var synopsisEl = document.getElementById('details-overview') || this.container.querySelector('.details-synopsis');
      if (synopsisEl) {
        synopsisEl.textContent = data.overview || 'No synopsis available.';
      }
    },

    createCastChip: function (actor, index) {
      var card = document.createElement('div');
      card.className = 'cast-item cast-chip';
      card.setAttribute('data-nav', 'true');
      card.setAttribute('data-nav-group', 'details-cast');
      card.setAttribute('data-nav-index', String(index));
      card.setAttribute('tabindex', '-1');

      var profilePath = actor.profile_path || actor.profileUrl;
      var profileUrl = actor.profileUrl || (profilePath && profilePath.indexOf('http') === 0 ? profilePath : (global.TmdbClient ? global.TmdbClient.getProfileUrl(profilePath) : ('https://image.tmdb.org/t/p/w185' + (profilePath || ''))));

      var avatarDiv = document.createElement('div');
      avatarDiv.className = 'cast-avatar';

      var img = document.createElement('img');
      img.className = 'cast-photo';
      img.alt = actor.name || 'Cast';
      img.loading = 'lazy';
      if (profileUrl) {
        img.src = profileUrl;
      }
      img.onerror = function () {
        this.onerror = null;
        this.src = 'data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="80" height="80" viewBox="0 0 80 80"><circle cx="40" cy="40" r="40" fill="%2326292f"/><circle cx="40" cy="32" r="16" fill="%239aa0a6"/><path d="M20 66 C20 52 30 48 40 48 C50 48 60 52 60 66 Z" fill="%239aa0a6"/></svg>';
      };
      avatarDiv.appendChild(img);
      card.appendChild(avatarDiv);

      var nameSpan = document.createElement('span');
      nameSpan.className = 'cast-name';
      nameSpan.textContent = actor.name || 'Unknown';
      card.appendChild(nameSpan);

      var role = actor.character || actor.role;
      if (role) {
        var roleSpan = document.createElement('span');
        roleSpan.className = 'cast-role';
        roleSpan.textContent = role;
        card.appendChild(roleSpan);
      }

      return card;
    },

    renderCast: function (cast) {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var shelf = document.getElementById('details-cast-shelf');
      var rail = document.getElementById('details-cast-rail');
      if (!rail) {
        var existingCast = this.container.querySelector('[data-nav-group="details-cast"]');
        if (existingCast) rail = existingCast.closest('.shelf-rail');
      }
      if (!rail) return;

      var topCast = (cast || []).slice(0, 12);
      if (shelf) {
        shelf.style.display = topCast.length > 0 ? 'block' : 'none';
      }

      var fragment = document.createDocumentFragment();
      for (var i = 0; i < topCast.length; i++) {
        var actor = topCast[i];
        var item = getCardFactory().createCastCard ? getCardFactory().createCastCard(actor, i) : this.createCastChip(actor, i);
        fragment.appendChild(item);
      }

      clearElement(rail);
      rail.appendChild(fragment);
    },

    renderSeasonSelector: function (numSeasons) {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var bar = document.getElementById('details-season-selector') || this.container.querySelector('.season-selector-bar');
      var epShelf = document.getElementById('details-episodes-shelf') || (this.container.querySelector('[data-nav-group="details-episodes"]') && this.container.querySelector('[data-nav-group="details-episodes"]').closest('.content-shelf'));
      if (!bar && epShelf) {
        bar = epShelf.querySelector('.season-selector-bar');
      }
      if (!bar) return;

      bar.style.display = 'flex';
      if (epShelf) epShelf.style.display = 'block';

      var self = this;
      var count = Math.max(1, numSeasons || 1);
      var fragment = document.createDocumentFragment();

      for (var s = 1; s <= count; s++) {
        var pill = document.createElement('button');
        var isActive = s === self.activeSeason;
        pill.className = 'season-pill season-tab-btn' + (isActive ? ' active' : '');
        pill.setAttribute('data-nav', 'true');
        pill.setAttribute('data-nav-group', 'season-pills');
        pill.setAttribute('data-season', String(s));
        pill.textContent = 'Season ' + s;

        (function (seasonNum, pillEl) {
          pillEl.addEventListener('click', function () {
            self.activeSeason = seasonNum;
            var allPills = bar.querySelectorAll('.season-pill');
            allPills.forEach(function (p) { p.classList.remove('active'); });
            pillEl.classList.add('active');

            if (self.item) {
              var id = self.item.id || self.item.tmdbId;
              self.loadSeason(id, seasonNum);
            }
          });
        })(s, pill);

        fragment.appendChild(pill);
      }

      clearElement(bar);
      bar.appendChild(fragment);
    },

    loadSeason: function (tvId, seasonNumber) {
      var self = this;
      var sNum = seasonNumber || 1;
      if (!global.TmdbClient) return;

      return global.TmdbClient.getTvSeason(tvId, sNum).then(function (seasonData) {
        if (sNum !== self.activeSeason) return;
        if (!seasonData || seasonData.error) return;
        var episodes = seasonData.episodes || [];
        self.renderEpisodes(episodes, sNum);
      }).catch(function (err) {
        if (sNum !== self.activeSeason) return;
        console.error('[DetailsViewController] Failed to load season:', err);
      });
    },

    renderEpisodes: function (episodes, seasonNumber) {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var rail = document.getElementById('details-episodes-rail');
      if (!rail) {
        var existingEp = this.container.querySelector('[data-nav-group="details-episodes"]');
        if (existingEp) rail = existingEp.closest('.shelf-rail');
      }
      if (!rail) return;

      var fragment = document.createDocumentFragment();
      for (var i = 0; i < episodes.length; i++) {
        var card = getCardFactory().createEpisodeCard(episodes[i], seasonNumber, i);
        fragment.appendChild(card);
      }

      clearElement(rail);
      rail.appendChild(fragment);
    },

    hideSeasonSelector: function () {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var bar = document.getElementById('details-season-selector') || this.container.querySelector('.season-selector-bar');
      if (bar) bar.style.display = 'none';

      var epShelf = document.getElementById('details-episodes-shelf') || (this.container.querySelector('[data-nav-group="details-episodes"]') && this.container.querySelector('[data-nav-group="details-episodes"]').closest('.content-shelf'));
      if (epShelf) epShelf.style.display = 'none';
    },

    renderRecommendations: function (items) {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var recShelf = this.container.querySelector('.details-recommendations-shelf');
      var rail = document.getElementById('details-recommendations-rail');
      if (!recShelf && rail) {
        recShelf = rail.closest('.content-shelf');
      }

      if (!rail) {
        var scrollPane = this.container.querySelector('.view-scroll-pane') || this.container;
        recShelf = document.createElement('section');
        recShelf.className = 'content-shelf details-recommendations-shelf';

        var headerDiv = document.createElement('div');
        headerDiv.className = 'shelf-header';
        var titleH2 = document.createElement('h2');
        titleH2.className = 'shelf-title';
        titleH2.textContent = 'More Like This';
        headerDiv.appendChild(titleH2);
        recShelf.appendChild(headerDiv);

        var railDiv = document.createElement('div');
        railDiv.id = 'details-recommendations-rail';
        railDiv.className = 'shelf-rail';
        recShelf.appendChild(railDiv);

        scrollPane.appendChild(recShelf);
        rail = railDiv;
      }

      if (recShelf) recShelf.style.display = 'block';
      if (!rail) return;

      var recItems = items || [];
      var fragment = document.createDocumentFragment();
      var maxItems = Math.min(recItems.length, 12);

      for (var i = 0; i < maxItems; i++) {
        var card = getCardFactory().createPosterCard(recItems[i], 'details-recommendations', i, { mediaType: 'movie' });
        fragment.appendChild(card);
      }

      clearElement(rail);
      rail.appendChild(fragment);
    },

    hideRecommendations: function () {
      if (!this.container) this.container = document.getElementById('view-details');
      if (!this.container) return;

      var recShelf = this.container.querySelector('.details-recommendations-shelf');
      if (recShelf) recShelf.style.display = 'none';
    }
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = DetailsViewController;
  }
  global.DetailsViewController = DetailsViewController;

})(typeof window !== 'undefined' ? window : this);

