  align-items: center;
  gap: 16px;
  margin-top: 16px;
  white-space: nowrap;
}

.details-actions .btn,
.details-actions .dbtn,
.dbtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  height: 56px;
  padding: 0 32px;
  border-radius: var(--cinema-radius-tab, 30px);
  font-family: var(--cinema-font-family, var(--font-family-base));
  font-size: 22px;
  font-weight: 500;
  background: rgba(232, 234, 237, 0.16);
  color: #e8eaed;
  border: 2px solid transparent;
  cursor: pointer;
  outline: none;
  text-decoration: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), background-color 0.18s ease, color 0.18s ease, box-shadow 0.2s ease, border-color 0.18s ease;
  will-change: transform;
}

.details-actions .btn svg,
.details-actions .dbtn svg,
.dbtn svg {
  width: 24px;
  height: 24px;
  fill: currentColor;
  flex-shrink: 0;
}

/* Primary Play Button */
#details-play-btn,
.details-actions .btn-primary,
.details-actions .dbtn-primary {
  background: #FFFFFF;
  color: #202124;
  font-weight: 600;
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.4);
}

#details-play-btn svg,
.details-actions .btn-primary svg {
  fill: #202124;
}

/* High-Contrast Spatial Remote Focus Halos */
#details-play-btn:focus,
#details-play-btn.focused,
#details-play-btn.tv-focused {
  background: var(--color-accent-primary, #95FF50);
  color: #04120B;
  transform: scale(1.08);
  border-color: #FFFFFF;
  box-shadow: 0 0 0 5px #FFFFFF, 0 0 28px rgba(149, 255, 80, 0.75);
}

#details-play-btn:focus svg,
#details-play-btn.focused svg,
#details-play-btn.tv-focused svg {
  fill: #04120B;
}

.details-actions .btn-secondary:focus,
.details-actions .btn-secondary.focused,
.details-actions .btn-secondary.tv-focused,
.details-actions .dbtn:focus,
.details-actions .dbtn.focused,
.details-actions .dbtn.tv-focused,
.dbtn:focus,
.dbtn.focused,
.dbtn.focus {
  background: #e8eaed;
  color: #202124;
  transform: scale(1.08);
  border-color: #FFFFFF;
  box-shadow: 0 0 0 5px #FFFFFF, 0 12px 30px rgba(0, 0, 0, 0.6);
}

.details-actions .btn-secondary:focus svg,
.details-actions .btn-secondary.focused svg,
.details-actions .btn-secondary.tv-focused svg,
.details-actions .dbtn:focus svg,
.details-actions .dbtn.focused svg,
.dbtn:focus svg {
  fill: #202124;
  stroke: #202124;
}

/* Cast & Crew Sleek Pill Chips */
.cast-item,
.cast-chip {
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 12px;
  padding: 8px 20px 8px 10px;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: var(--cinema-radius-tab, 30px);
  cursor: pointer;
  outline: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), background-color 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
  white-space: nowrap;
}

.cast-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  overflow: hidden;
  background-color: var(--cinema-surface-card, #26292f);
  border: 1px solid rgba(255, 255, 255, 0.15);
  flex-shrink: 0;
}

.cast-avatar img,
.cast-photo {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.cast-name {
  font-size: 18px;
  font-weight: 500;
  color: var(--cinema-text-primary, #e8eaed);
  line-height: 1.2;
}

.cast-role {
  font-size: 14px;
  color: var(--cinema-text-muted, #9aa0a6);
  line-height: 1.2;
}

.cast-role::before {
  content: "·";
  margin: 0 6px;
  color: rgba(255, 255, 255, 0.3);
}

.cast-item:focus,
.cast-item.focused,
.cast-item.tv-focused {
  background: #e8eaed;
  border-color: #FFFFFF;
  transform: scale(1.08);
  box-shadow: 0 0 0 4px #FFFFFF, 0 10px 24px rgba(0, 0, 0, 0.6);
}

.cast-item:focus .cast-name,
.cast-item.focused .cast-name {
  color: #202124;
}

.cast-item:focus .cast-role,
.cast-item.focused .cast-role {
  color: #5f6368;
}

/* Season Selector Bar */
.season-selector-bar,
#details-season-selector {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 16px;
  padding-left: 2px;
}

.season-pill {
  padding: 8px 24px;
  border-radius: var(--cinema-radius-tab, 30px);
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.14);
  color: var(--cinema-text-secondary, #bdc1c6);
  font-family: var(--cinema-font-family, var(--font-family-base));
  font-size: 17px;
  font-weight: 500;
  cursor: pointer;
  outline: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), background-color 0.18s ease, color 0.18s ease, border-color 0.18s ease;
  white-space: nowrap;
}

.season-pill.active {
  background: rgba(232, 234, 237, 0.22);
  color: #FFFFFF;
  font-weight: 600;
  border-color: rgba(255, 255, 255, 0.4);
}

.season-pill:focus,
.season-pill.focused,
.season-pill.tv-focused {
  background: #FFFFFF;
  color: #202124;
  font-weight: 600;
  transform: scale(1.08);
  border-color: #FFFFFF;
  box-shadow: 0 0 0 4px #FFFFFF, 0 8px 24px rgba(0, 0, 0, 0.5);
}

/* 16:9 Episode Still Cards with Rounded 14px Radius */
.card-episode {
  flex: 0 0 320px;
  width: 320px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
  text-decoration: none;
  border-radius: 14px;
  outline: none;
  transition: transform 0.2s cubic-bezier(0.2, 0, 0, 1), box-shadow 0.2s ease;
  contain: layout style;
  will-change: transform;
}

.episode-media {
  width: 320px;
  height: 180px;
  border-radius: 14px;
  overflow: hidden;
  position: relative;
  background: var(--cinema-surface-card, #26292f);
  border: 1px solid rgba(255, 255, 255, 0.10);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.45);
}

.episode-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  background-color: #1a1c20;
}

.episode-badge {
  position: absolute;
  top: 10px;
  left: 10px;
  background: rgba(14, 16, 20, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 9999px;
  padding: 4px 10px;
  font-size: 13px;
  font-weight: 700;
  color: #FFFFFF;
}

.episode-runtime {
  position: absolute;
  bottom: 10px;
  right: 10px;
  background: rgba(14, 16, 20, 0.85);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 9999px;
  padding: 3px 8px;
  font-size: 12px;
  font-weight: 500;
  color: #bdc1c6;
}

.episode-info {
  padding-top: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.episode-title {
  font-size: 17px;
  font-weight: 600;
  color: var(--cinema-text-primary, #e8eaed);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.episode-overview {
  font-size: 13px;
  color: var(--cinema-text-muted, #9aa0a6);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  line-height: 1.4;
}

.card-episode:focus,
.card-episode.focused,
.card-episode.tv-focused {
  transform: scale(1.08);
  z-index: 10;
}

.card-episode:focus .episode-media,
.card-episode.focused .episode-media,
.card-episode.tv-focused .episode-media {
  border-color: #FFFFFF;
  box-shadow: 0 0 0 5px #FFFFFF, 0 16px 36px rgba(0, 0, 0, 0.7);
}

.card-episode:focus .episode-title,
.card-episode.focused .episode-title {
  color: #FFFFFF;
}
